fn swap(arr: &Vec<i32>, i: usize, j: usize) -> Vec<i32> {
    // If the indices are the same, just return a clone of the original array.
    if i == j {
        return arr.clone();
    }

    // Clone the input array to create a new array for the output
    let mut result = arr.clone();

    // Swap the elements at indices i and j
    let temp = result[i];
    result[i] = result[j];
    result[j] = temp;

    result
}